# Studyo 0.5.54 yamasi: seslendirmede harekesiz Arap harfli satir okunmaz (3+ Arapca kelime, harflerin %60+'i Arap harfi,
# hareke %5'ten az, Turkce kelime 2'den az). Harekeli ayet, Turkce mealli satir ve kisa Arapca soz okunur. Yazili ciktilar degismez.
# 0.5.53 uzerine. Kod klasorunde: cd /DATA/AppData/dedplay-studyo/kod/studyo && python3 studyo_0554_yama.py
# Tekrar calistirilabilir: dosya zaten yeniyse ATLANDI; ne eski ne yeniyse hicbir seye dokunmadan HATA.
import base64, hashlib, os, sys, zlib
D = [
    ('app/ses.py', '1978c3a24c45c047c23f4865b80cb2e1', 'd72dc45687868b18916a5c544911cec2',
     ''),
    ('kutuphane/main.py', 'bef7734a47678344529780db4c56670c', 'd91f7f652cf67b03724d4c8fe5380818',
     ''),
    ('tests/test_0548.py', '84ce73c6aac54c1425819392948fd454', 'fb15146a731aa5bf6922da5ece3ff9a3',
     ''),
    ('tests/test_0554.py', None, 'd00e607d019f1ed438068780226c001c',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    os.makedirs(os.path.dirname(yol) or '.', exist_ok=True)
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
